    /// <summary>Originalzeichnung eines Zeichens; null, wenn es (noch) keine bestätigte gibt.</summary>
    public static IReadOnlyList<SignArtworkLayer>? For(string number) =>
        Werke.TryGetValue(number, out var werk) ? werk : null;

    /// <summary>Wie viele Zeichen bereits im Original vorliegen - für Tests und die Doku.</summary>
    public static int Count => Werke.Count;

    /// <summary>Alle Nummern mit Originalzeichnung.</summary>
    public static IReadOnlyCollection<string> Numbers => Werke.Keys;
